-- Additive UI ledger. Legacy columns remain compatibility projections.
ALTER TABLE workspaces ADD COLUMN version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE workspaces ADD COLUMN default_conversation_id TEXT;
ALTER TABLE workspaces ADD COLUMN lead_connection TEXT;
ALTER TABLE roles ADD COLUMN display_name TEXT;
ALTER TABLE roles ADD COLUMN version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE roles ADD COLUMN chat_connection TEXT;
UPDATE roles SET display_name=name;
ALTER TABLE tasks ADD COLUMN repository_id TEXT REFERENCES repositories(id);
UPDATE tasks SET repository_id=(SELECT r.id FROM repositories r JOIN workflows f ON f.workspace_id=r.workspace_id WHERE f.id=tasks.workflow_id);
CREATE TABLE workflow_repositories (workflow_id TEXT NOT NULL REFERENCES workflows(id), repository_id TEXT NOT NULL REFERENCES repositories(id), base_commit TEXT NOT NULL, integration_ref TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', PRIMARY KEY(workflow_id,repository_id));
INSERT INTO workflow_repositories SELECT f.id,r.id,f.base_commit,f.integration_ref,'active' FROM workflows f JOIN repositories r ON r.workspace_id=f.workspace_id;

CREATE TABLE conversations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), client_message_id TEXT, recipient_agent_id TEXT NOT NULL REFERENCES roles(id), role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(workspace_id,client_message_id));
CREATE TABLE agent_turns (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), message_id TEXT NOT NULL UNIQUE REFERENCES messages(id), agent_id TEXT NOT NULL REFERENCES roles(id), status TEXT NOT NULL CHECK(status IN ('queued','running','stopping','completed','failed','cancelled','interrupted')), configuration TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, cleanup_status TEXT NOT NULL DEFAULT 'pending', error TEXT, created_at TEXT NOT NULL, started_at TEXT, ended_at TEXT);
CREATE TABLE message_chunks (seq INTEGER PRIMARY KEY AUTOINCREMENT, turn_id TEXT NOT NULL REFERENCES agent_turns(id), text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX turn_queue ON agent_turns(status,created_at);
CREATE TABLE execution_leases (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL CHECK(owner_type IN ('run','turn')), owner_id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id), agent_id TEXT NOT NULL REFERENCES roles(id), capacity TEXT NOT NULL CHECK(capacity IN ('lead','developer','reviewer')), cleanup_status TEXT NOT NULL DEFAULT 'pending', acquired_at TEXT NOT NULL, released_at TEXT, UNIQUE(owner_type,owner_id));
CREATE UNIQUE INDEX one_execution_per_agent ON execution_leases(agent_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX one_lead_turn_per_workspace ON execution_leases(workspace_id) WHERE released_at IS NULL AND capacity='lead';
INSERT INTO execution_leases SELECT 'lease-'||r.id,'run',r.id,f.workspace_id,r.role_id,CASE r.purpose WHEN 'review' THEN 'reviewer' ELSE 'developer' END,r.cleanup_status,r.created_at,r.slot_released_at FROM runs r JOIN tasks t ON t.id=r.task_id JOIN workflows f ON f.id=t.workflow_id;
DROP TRIGGER run_global_capacity;
CREATE TRIGGER lease_capacity BEFORE INSERT ON execution_leases WHEN NEW.released_at IS NULL AND ((NEW.capacity='lead' AND (SELECT count(*) FROM execution_leases WHERE released_at IS NULL AND capacity='lead')>=4) OR (NEW.capacity<>'lead' AND ((SELECT count(*) FROM execution_leases WHERE released_at IS NULL AND capacity<>'lead')>=(SELECT total FROM scheduler_limits WHERE id=1) OR (NEW.capacity='reviewer' AND (SELECT count(*) FROM execution_leases WHERE released_at IS NULL AND capacity='reviewer')>=1) OR (NEW.capacity='developer' AND (SELECT count(*) FROM execution_leases WHERE released_at IS NULL AND capacity='developer')>=(SELECT developers FROM scheduler_limits WHERE id=1))))) BEGIN SELECT RAISE(ABORT,'capacity exceeded'); END;
CREATE TRIGGER run_lease_insert AFTER INSERT ON runs BEGIN INSERT INTO execution_leases(id,owner_type,owner_id,workspace_id,agent_id,capacity,cleanup_status,acquired_at,released_at) VALUES('lease-'||NEW.id,'run',NEW.id,(SELECT f.workspace_id FROM workflows f JOIN tasks t ON t.workflow_id=f.id WHERE t.id=NEW.task_id),NEW.role_id,CASE NEW.purpose WHEN 'review' THEN 'reviewer' ELSE 'developer' END,NEW.cleanup_status,NEW.created_at,NEW.slot_released_at); END;
CREATE TRIGGER run_lease_update AFTER UPDATE OF cleanup_status,slot_released_at ON runs BEGIN UPDATE execution_leases SET cleanup_status=NEW.cleanup_status,released_at=NEW.slot_released_at WHERE owner_type='run' AND owner_id=NEW.id; END;
CREATE TRIGGER message_scope BEFORE INSERT ON messages WHEN (SELECT workspace_id FROM conversations WHERE id=NEW.conversation_id)<>NEW.workspace_id OR (SELECT workspace_id FROM roles WHERE id=NEW.recipient_agent_id)<>NEW.workspace_id BEGIN SELECT RAISE(ABORT,'cross-workspace message'); END;
CREATE TRIGGER turn_scope BEFORE INSERT ON agent_turns WHEN (SELECT workspace_id FROM messages WHERE id=NEW.message_id)<>NEW.workspace_id OR (SELECT conversation_id FROM messages WHERE id=NEW.message_id)<>NEW.conversation_id OR (SELECT recipient_agent_id FROM messages WHERE id=NEW.message_id)<>NEW.agent_id BEGIN SELECT RAISE(ABORT,'cross-workspace turn'); END;
CREATE TABLE workspace_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL REFERENCES workspaces(id), type TEXT NOT NULL, entity_id TEXT NOT NULL, entity_version INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL);
CREATE INDEX workspace_event_cursor ON workspace_events(workspace_id,seq);
CREATE TRIGGER workspace_event_retention AFTER INSERT ON workspace_events BEGIN DELETE FROM workspace_events WHERE seq<NEW.seq-10000; END;
CREATE TRIGGER task_event_projection AFTER INSERT ON task_events BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,payload,occurred_at) VALUES((SELECT workspace_id FROM workflows WHERE id=NEW.workflow_id),NEW.type,COALESCE(NEW.run_id,NEW.task_id,NEW.workflow_id),json_object('taskEventSeq',NEW.event_seq),NEW.occurred_at); END;
CREATE TRIGGER workspace_insert_event AFTER INSERT ON workspaces BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.id,'workspace.created',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER workspace_update_event AFTER UPDATE ON workspaces BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.id,'workspace.updated',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER role_insert_event AFTER INSERT ON roles BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'agent.created',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER role_update_event AFTER UPDATE ON roles BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'agent.updated',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER conversation_insert_event AFTER INSERT ON conversations BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'conversation.created',NEW.id,NEW.version,NEW.created_at); END;
CREATE TRIGGER message_insert_event AFTER INSERT ON messages BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'message.created',NEW.id,NEW.version,NEW.created_at); END;
CREATE TRIGGER message_update_event AFTER UPDATE ON messages BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'message.updated',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER turn_insert_event AFTER INSERT ON agent_turns BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'turn.queued',NEW.id,NEW.version,NEW.created_at); END;
CREATE TRIGGER turn_update_event AFTER UPDATE ON agent_turns BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'turn.updated',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER chunk_insert_event AFTER INSERT ON message_chunks BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,payload,occurred_at) VALUES((SELECT workspace_id FROM agent_turns WHERE id=NEW.turn_id),'turn.chunk',NEW.turn_id,json_object('chunkSeq',NEW.seq),NEW.created_at); END;
INSERT INTO schema_migrations(version,applied_at) VALUES(4,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
